function fechaISO(value) {
 if (typeof value !== 'string') return null;
 const s=value.trim().toLowerCase(); let y,m,d; let a=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
 if(a) [,y,m,d]=a; else {a=s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/); if(a) [,d,m,y]=a; else { a=s.match(/^(\d{1,2})\s+(?:de\s+)?(ene(?:ro)?|feb(?:rero)?|mar(?:zo)?|abr(?:il)?|may(?:o)?|jun(?:io)?|jul(?:io)?|ago(?:sto)?|sep(?:tiembre)?|oct(?:ubre)?|nov(?:iembre)?|dic(?:iembre)?)\s+(?:de\s+)?(\d{4})$/); if(!a) return null; d=a[1];y=a[3];m=['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'].indexOf(a[2].slice(0,3))+1; }}
 y=+y;m=+m;d=+d;let dt=new Date(Date.UTC(y,m-1,d)); if(dt.getUTCFullYear()!==y||dt.getUTCMonth()+1!==m||dt.getUTCDate()!==d)return null; return `${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
}
function importeNumero(v) {
 if(typeof v==='number') return Number.isFinite(v)?v:null;
 if(typeof v!=='string') return null;
 let s=v.trim().replace(/^(?:ARS|USD|EUR|\$|€)\s*/i,'').replace(/\s*(?:ARS|USD|EUR)$/i,'').trim();
 if (/^-?\d{1,3}(?:\.\d{3})+,\d{2}$/.test(s)) s=s.replace(/\./g,'').replace(',','.');
 else if (/^-?\d{1,3}(?:,\d{3})+\.\d{2}$/.test(s)) s=s.replace(/,/g,'');
 else if (/^-?\d+,\d{1,2}$/.test(s)) s=s.replace(',','.');
 else if (!/^-?\d+(?:\.\d{1,2})?$/.test(s)) return null;
 const n=Number(s);return Number.isFinite(n)?n:null;
}
return $input.all().map(item=>{
 try {
  const raw=item.json.content?.parts?.[0]?.text??item.json.candidates?.[0]?.content?.parts?.find(x=>x.text)?.text??'';
  const p=JSON.parse(raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''));
  const fecha=fechaISO(p.fecha); const importe=importeNumero(p.importe);
  const categorias=Array.isArray(p.categorias)?p.categorias.filter(x=>typeof x==='string').map(x=>x.trim().toLocaleLowerCase('es')).filter(Boolean):[];
  const prioridad=typeof p.prioridad==='string'?p.prioridad.trim().toLocaleLowerCase('es'):null;
  const valido=typeof p.ticket_id==='string' && p.ticket_id.trim().length>0 && fecha && categorias.length>0 && typeof p.revision_humana==='boolean';
  // La prioridad generada no tiene verificación de fuente; revisión obligatoria.
  const revision=true;
  return {json:{ticket_id:p.ticket_id??null,fecha,categorias,prioridad,importe,valido:Boolean(valido),revision_humana:revision,estado:revision?'revision':'procesado'}};
 }catch(e){return {json:{estado:'revision',valido:false,revision_humana:true,error:'Respuesta invalida'}};}
