 let texto=protegido.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,'[EMAIL]').replace(/(?:\+?\d[\d ()-]{7,}\d)/g,'[TELEFONO_O_ID]').slice(0,12000);texto=texto.replace(/\[FECHA_([A-Z])\]/g,(_,k)=>fechas[k.charCodeAt(0)-65]);
